std::string transport_name(std::uint8_t ip_proto) {
	switch(ip_proto) {
	case 6: return "TCP";
	case 17: return "UDP";
	case 1: return "ICMP";
	case 58: return "ICMPv6";
	default: return "IP " + std::to_string(ip_proto);
	}
}

const char *delivery_name(const ip_addr &address) {
	if(stream_id::is_ipv4_broadcast(address)) return "broadcast";
	if(stream_id::is_multicast(address)) return "multicast";
	return "unicast";
}

