int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.lifetime.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count_total.inc();

	return 0;
}

