int streams::process_info(info i, const std::vector<std::string> &target_ids, const std::string &stream_name) {
    expire_streams(i.time_epoch);

	flow_id fid = make_flow_id(i.interface_id,
	                           i.ip_proto,
	                           i.src.addr, i.src.port,
	                           i.dst.addr, i.dst.port,
	                           i.vlan);

	stream_id sid = make_stream_id(i.interface_id,
	                               i.proto,
	                               i.ip_proto,
	                               i.src.addr, i.src.port,
	                               i.dst.addr, i.dst.port,
	                               i.vlan);

	if(should_use_reverse_match(i.ip_proto)) {
		auto reverse_it = m_reverse_stream_index.find(reverse_flow_id(fid));
		if(reverse_it != m_reverse_stream_index.end()) {
			sid = reverse_it->second;
		}
	}

	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(make_stream_key(sid), stream_name);
	}

	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		auto s = std::make_unique<stream>(sid, i.interface_name, m_events);
		s->emit_detected(i.time_epoch);
		int rc = s->process(i);
		m_streams.emplace(sid, std::move(s));
		m_reverse_stream_index[fid] = sid;
		return rc;
	}

	m_reverse_stream_index[fid] = sid;
	return it->second->process(i);
}

